import{_ as h,o as n,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"&quot;Test không phải để phán xét learner&quot;","description":"","frontmatter":{},"headers":[],"relativePath":"mental-models/test-khong-phan-xet.md","filePath":"mental-models/test-khong-phan-xet.md"}'),o={name:"mental-models/test-khong-phan-xet.md"};function c(u,t,e,g,r,l){return n(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="quot-test-khong-phai-đe-phan-xet-learner-quot" tabindex="-1">&quot;Test không phải để phán xét learner&quot; <a class="header-anchor" href="#quot-test-khong-phai-đe-phan-xet-learner-quot" aria-label="Permalink to &quot;&amp;quot;Test không phải để phán xét learner&amp;quot;&quot;">​</a></h1><p>Trên trang này# &quot;Test không phải để phán xét learner&quot; <a href="#test-khong-phai-đe-phan-xet-learner">​</a> Với hầu hết mọi người, kiểm tra nghĩa là bị đánh giá: làm tốt thì được khen, làm tệ thì bị chê. Với Nemo12, một bài đo là <strong>câu hỏi của hệ thống về chính sự thiếu hiểu biết của nó</strong> — không phải bản án về đứa trẻ.</p><h2 id="đoi-ai-la-chu-ngu-​" tabindex="-1">Đổi ai là chủ ngữ <a href="#đoi-ai-la-chu-ngu">​</a> <a class="header-anchor" href="#đoi-ai-la-chu-ngu-​" aria-label="Permalink to &quot;Đổi ai là chủ ngữ [​](#đoi-ai-la-chu-ngu)&quot;">​</a></h2><p>Cách hiểu thông thường&quot;Bài kiểm tra cho biết learner giỏi tới đâu.&quot; Chủ ngữ là đứa trẻ. Kết quả là một phán xét về nó. Cách Nemo12 hiểu&quot;Bài đo cho biết hệ thống còn thiếu thông tin gì.&quot; Chủ ngữ là hệ thống. Kết quả là dữ liệu để hệ thống làm việc tốt hơn. Nghe như một trò chơi chữ, nhưng nó đổi mọi thứ về sau. Nếu bài đo là phán xét, thì làm sai là thất bại, và phản ứng hợp lý của một đứa trẻ là <strong>giấu chỗ mình không biết</strong>. Nếu bài đo là thu thập thông tin, thì làm sai là dữ liệu hữu ích, và phản ứng hợp lý là <strong>trung thực</strong>. Một hệ thống không biết học sinh thật sự không hiểu chỗ nào thì không giúp được gì. Vì vậy sự trung thực không phải phẩm chất đạo đức ở đây — nó là điều kiện kỹ thuật để hệ thống hoạt động.</p><h2 id="bon-thiet-ke-cu-the-​" tabindex="-1">Bốn thiết kế cụ thể <a href="#bon-thiet-ke-cu-the">​</a> <a class="header-anchor" href="#bon-thiet-ke-cu-the-​" aria-label="Permalink to &quot;Bốn thiết kế cụ thể [​](#bon-thiet-ke-cu-the)&quot;">​</a></h2><p><strong>Nút &quot;Chưa biết&quot; là lựa chọn hợp lệ.</strong> Không phải hình phạt, không tính là sai theo cách thông thường. Nó là tín hiệu trung thực và có giá trị thông tin cao hơn một câu đoán bừa may mắn đúng. <strong>Đoán bừa không bị phạt — nó bị bỏ qua.</strong> Learner mệt, bấm bừa 10 câu, sẽ không bị kết luận &quot;yếu&quot;. Phiên đó được đánh dấu <strong>không đủ dữ liệu tin cậy</strong> và hẹn đo lại. Hình phạt cho việc mệt không nên là bị bắt học lại thứ mình đã biết. <strong>Bài đo dừng khi đủ, không kéo dài cho đủ số câu.</strong> Learner không phải ngồi qua 34 câu nữa chỉ để hoàn thành một khuôn mẫu. <strong>Không có bảng xếp hạng.</strong> Nemo12 không so learner với learner khác. Đối tượng so sánh duy nhất là chính con của ba tuần trước.</p><h2 id="ket-qua-kem-khong-phai-tin-xau-​" tabindex="-1">Kết quả kém không phải tin xấu <a href="#ket-qua-kem-khong-phai-tin-xau">​</a> <a class="header-anchor" href="#ket-qua-kem-khong-phai-tin-xau-​" aria-label="Permalink to &quot;Kết quả kém không phải tin xấu [​](#ket-qua-kem-khong-phai-tin-xau)&quot;">​</a></h2><p>Một bài đo cho kết quả thấp ở một phần vừa làm được ba việc có ích:</p><ul><li>Chỉ ra chính xác chỗ cần dành thời gian.</li><li>Ngăn learner đi tiếp trên một nền chưa vững.</li><li>Cho hệ thống thông tin để không giao nhầm bài trong nhiều tuần tới. So với việc lỗ hổng đó ẩn thêm sáu tháng rồi lộ ra giữa kỳ thi thật, phát hiện sớm là kết quả tốt. Nói với con điều này — thật lòng, không phải để an ủi — đổi hẳn quan hệ của con với việc bị kiểm tra.</li></ul><h2 id="nhung-con-ky-thi-that-thi-sao-​" tabindex="-1">Nhưng còn kỳ thi thật thì sao? <a href="#nhung-con-ky-thi-that-thi-sao">​</a> <a class="header-anchor" href="#nhung-con-ky-thi-that-thi-sao-​" aria-label="Permalink to &quot;Nhưng còn kỳ thi thật thì sao? [​](#nhung-con-ky-thi-that-thi-sao)&quot;">​</a></h2><p>Kỳ thi tuyển sinh đúng là phán xét. Nó quyết định con vào đâu, và Nemo12 không giả vờ ngược lại. Điều cần tách bạch: <strong>kỳ thi thật hiếm, các phép đo trong quá trình học thì rất nhiều</strong>. Nếu mọi phép đo trong hai năm chuẩn bị đều mang tính phán xét, learner sẽ bước vào kỳ thi thật với hai năm lo lắng tích tụ — và điều đó làm kết quả tệ đi, không tốt lên. Cách chuẩn bị tốt cho một kỳ thi có tính phán xét là có rất nhiều phép đo <strong>không</strong> phán xét trước đó.</p><h2 id="o-nha-ba-cau-nen-đoi-​" tabindex="-1">Ở nhà: ba câu nên đổi <a href="#o-nha-ba-cau-nen-đoi">​</a> <a class="header-anchor" href="#o-nha-ba-cau-nen-đoi-​" aria-label="Permalink to &quot;Ở nhà: ba câu nên đổi [​](#o-nha-ba-cau-nen-đoi)&quot;">​</a></h2><p>Thay vìThử&quot;Sao lại sai chỗ này?&quot;&quot;Chỗ này con nghĩ thế nào?&quot;&quot;Con không tập trung à?&quot;&quot;Đọc đề xong con hiểu là gì?&quot;&quot;Bạn A được 9 đấy.&quot;&quot;Bài này so với tháng trước thì sao?&quot;Cột phải không phải là nói giảm nói tránh. Chúng là những câu hỏi <strong>thật sự cho thông tin</strong> — và chúng cũng giữ cho con không học được bài học rằng chỗ mình không biết là chỗ phải giấu. Dấu hiệu cần chú ý Nếu con bắt đầu giấu điểm, nói tránh về bài kiểm tra, hoặc chỉ làm những bài chắc chắn làm được — đó là dấu hiệu việc đo đã trở thành việc phán xét trong đầu con. Sửa điều này quan trọng hơn bất kỳ điểm số nào. Một phép đo tốt không nói &quot;con giỏi hay kém&quot;. Nó nói &quot;chỗ này đã rõ, chỗ kia thì chưa&quot; — và đó là câu nói không có gì để phải sợ. <a href="/mental-models/uncertainty">Mọi learner model đều có uncertainty →</a></p>',13)])])}const p=h(o,[["render",c]]);export{k as __pageData,p as default};
